sequenceDiagram(name = "SearchProcess") {
    val buyer = lifeline(name = "Buyer") { isActor = true }
    val webShop = lifeline(name = "WebShop")
    val searchService = lifeline(name = "SearchService")
    val productCatalog = lifeline(name = "ProductCatalog")

    message(from = buyer, to = webShop, label = "enterSearchTerm(term)")
    message(from = webShop, to = searchService, label = "findProducts(term)")
    reply(from = searchService, to = webShop, label = "results")

    alt("resultsFound") {
        message(from = webShop, to = productCatalog, label = "loadProductImages(results)")
        reply(from = productCatalog, to = webShop, label = "images")
        message(from = webShop, to = buyer, label = "displayResultsPage(results, images)")
    }
}

